def semver_sort(versions):
    def parse_version(v):
        # Split on '+' first to isolate build metadata
        if '+' in v:
            v_without_build = v.split('+')[0]
        else:
            v_without_build = v

        # Split on '-' to separate core version and pre-release
        if '-' in v_without_build:
            core_part, prerelease_part = v_without_build.split('-', 1)
        else:
            core_part = v_without_build
            prerelease_part = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part is None:
            prerelease_identifiers = None
        else:
            prerelease_identifiers = prerelease_part.split('.')

        return (major, minor, patch, prerelease_identifiers)

    def prerelease_key(identifiers):
        if identifiers is None:
            # No pre-release: sorts after pre-release versions
            return (1,)
        else:
            # Has pre-release: sorts before non-prerelease
            converted = []
            for identifier in identifiers:
                if identifier.isdigit():
                    converted.append((0, int(identifier)))
                else:
                    converted.append((1, identifier))
            return (0, tuple(converted))

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease_identifiers = parse_version(version)
        return (major, minor, patch, prerelease_key(prerelease_identifiers), index)

    indexed_versions = list(enumerate(versions))
    sorted_versions = sorted(indexed_versions, key=sort_key)

    return [v for _, v in sorted_versions]

